mapper.select:
SELECT EXISTS (
    SELECT 1 FROM (VALUES

            (#{segment.searchPathId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}::uuid,
             #{segment.startIndex}::integer)

    ) AS requested(path_id, start_order)
    WHERE NOT EXISTS (
        SELECT 1 FROM search_path_segment s
        WHERE s.search_path_id = requested.path_id AND s.start_point_order = requested.start_order
    )
)

SELECT sp.id, op.incident_id, op.id AS op_id, sp.account_id, sp.status, sp.version

WHERE 
ORDER BY sp.id LIMIT #{limit}

SELECT id, search_path_id, start_point_order, end_point_order, last_changed_path_version,
       movement_type, version, started_at, ended_at
FROM search_path_segment
WHERE search_path_id = #{pathId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
AND start_point_order < #{before}

    AND last_changed_path_version > #{lowerVersion}
    AND last_changed_path_version <= #{upperVersion}

ORDER BY start_point_order DESC, id
LIMIT #{limit}

SELECT point_id, client_ts, lon, lat, speed_mps, horizontal_accuracy_m,
       location_provider, elapsed_realtime_nanos
FROM search_path_gps_point
WHERE search_path_id = #{pathId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND point_order BETWEEN #{start} AND #{end}
ORDER BY point_order

