UPDATE search_path_segment
SET movement_type = #{segment.movementType},
    movement_type_source = #{segment.movementTypeSource},
    corrected_by_account_id = #{segment.correctedByAccountId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler},
    corrected_at = #{segment.correctedAt},
    version = #{segment.version},
    last_changed_path_version = #{segment.lastChangedPathVersion},
    updated_at = #{updatedAt}
WHERE id = #{segment.id,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND version = #{expectedVersion}
